import br.com.pelotavision.*;import org.opencv.core.*;import org.opencv.imgproc.Imgproc;import org.opencv.imgcodecs.Imgcodecs;import java.util.*;import java.nio.file.*;
class NativeSearchLimits {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static int hits(PelletDetector.Result result,List<Point> truth){boolean[] used=new boolean[truth.size()];int n=0;for(PelletDetector.Detection d:result.circles){int k=-1;double best=15;for(int i=0;i<truth.size();i++){double dist=Math.hypot(d.x-truth.get(i).x,d.y-truth.get(i).y);if(!used[i]&&dist<best){best=dist;k=i;}}if(k>=0){used[k]=true;n++;}}return n;}
 public static void main(String[] args)throws Exception{nu.pattern.OpenCV.loadLocally();Core.setNumThreads(2);Path out=Path.of(args[0]);StringBuilder csv=new StringBuilder("scene;truth;baseline_count;baseline_hits;selected_count;selected_hits;selected_option;duration_ms\n");
  for(int scene=0;scene<3;scene++){
   int w=800,h=600;Mat gray=new Mat(h,w,CvType.CV_8UC1);byte[] bg=new byte[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)bg[y*w+x]=(byte)(scene==1?200+35*x/w:scene==2?60+80*x/w:25+45*x/w);gray.put(0,0,bg);List<Point> truth=new ArrayList<>();
   for(int i=0;i<20;i++){Point center=new Point(80+160*(i%5),75+150*(i/5));truth.add(center);int radius=24+(i*7)%18;double value=scene==1?40+3*(i%5):scene==2?Math.min(235,120+80*center.x/w):175+8*(i%5);Imgproc.ellipse(gray,center,new Size(radius,radius*.9),i*13,0,360,new Scalar(value),-1,Imgproc.LINE_AA,0);}
   DetectionTuner.Report report=DetectionTuner.search(gray,new DetectionTuner.Option(3,75,false),new DetectionAssessment.Context(null,w,h,null,5),()->false,(a,b,c)->{},120000);PelletDetector.Result base=report.trials.get(0).result,best=report.best().result;int bh=hits(base,truth),sh=hits(best,truth);check(sh>=bh-1,"Suggestion lost known centers in illumination scene "+scene);check(sh>=18,"Too few known pellets");check(best.circles.size()-sh<=base.circles.size()-bh+1,"Too many new false candidates");csv.append(scene+";20;"+base.circles.size()+";"+bh+";"+best.circles.size()+";"+sh+";"+report.best().option.id+";"+report.durationMs+"\n");Imgcodecs.imwrite(out.resolve("analytic_illumination_"+scene+".png").toString(),gray);System.out.println("PASS analytic illumination "+scene+": baseline hits="+bh+" selected hits="+sh+" count="+best.circles.size());gray.release();
  }
  Files.writeString(out.resolve("analytic-lighting.csv"),csv.toString());Mat blank=new Mat(200,300,CvType.CV_8UC1,new Scalar(100));DetectionAssessment.Context context=new DetectionAssessment.Context(null,300,200,null,5);DetectionTuner.Option current=new DetectionTuner.Option(3,75,false);DetectionTuner.Report cancel=DetectionTuner.search(blank,current,context,()->true,(a,b,c)->{},30000);check(cancel.cancelled&&cancel.trials.size()==1,"Cancellation must stop after baseline");DetectionTuner.Report timed=DetectionTuner.search(blank,current,context,()->false,(a,b,c)->{},0);check(timed.timeLimited&&timed.trials.size()==1,"Budget must stop between options");Mat invalid=new Mat();DetectionTuner.Report failed=DetectionTuner.search(invalid,current,context,()->false,(a,b,c)->{},30000);check(failed.trials.size()==12&&failed.best()==null&&failed.weak(),"Option failures must remain explicit");blank.release();invalid.release();System.out.println("PASS cancellation, budget and explicit option failures");
 }
}
